mapper.select:
		select t.*
		  from PL_TARGET_DB t
		  LEFT JOIN PTL_PORTFOLIO_AUTHORITY aut
		    ON t.portfolio_id = aut.portfolio_id
		 where 1 = 1

		 AND t.portfolio_id in

                    #{portfolioId}



		 	and t.profit_type in 

                    #{profitType}



		    and aut.user_id in 

                    #{prodManager}



		   and t.cdate <= #{searchDateEnd,jdbcType=DATE}

select t.*,info.parent_portfolio_id parentId,
     row_number() over(partition by t.portfolio_id,t.profit_type order by t.cdate asc) rn
from PL_TARGET_DB t
left join PTL_PORTFOLIO info on info.portfolio_id = t.portfolio_id
where 1 = 1

 and t.cdate >= #{searchDateStart,jdbcType=DATE}


 and t.cdate <= #{searchDateEnd,jdbcType=DATE}


 and t.portfolio_id = #{portfolioId}

		with tempIds as (

		        select portfolio_id from PTL_PORTFOLIO where 1 = 1

		                      AND portfolio_id in

		                           #{portfolioId}


		        union 

		         select portfolio_id from PTL_PORTFOLIO where 1 = 1

		                      AND parent_portfolio_id in

		                           #{portfolioId}


		) 
		select t2.*,info.parent_portfolio_id parentId from (
		  select t1.*
		     from (
		         select t.*,
		               row_number() over(partition by t.portfolio_id,t.profit_type order by t.cdate desc) rn
		          from PL_TARGET_DB t
		          where 1 = 1
		         and t.PORTFOLIO_ID in (select portfolio_id from tempIds)

		           and t.cdate >= #{searchDateStart,jdbcType=DATE}


		           and t.cdate <= #{searchDateEnd,jdbcType=DATE}

		    ) t1
		where rn = 1 ) t2 
		left join PTL_PORTFOLIO info on info.portfolio_id = t2.portfolio_id
		where 1 = 1

		 	and t2.profit_type in 

                    #{profitType}



			AND t2.portfolio_id in (
				select portfolio_id from PTL_PORTFOLIO_AUTHORITY where user_id IN

				#{item}

			)

select fd.tareget_code, detail.tareget_type_code, detail.tareget_name from filter_detail fd INNER JOIN tilter_info ti ON fd.filter_code = ti.filter_code INNER JOIN TARGET_DETAIL detail ON fd.tareget_code = detail.tareget_code INNER JOIN TARGET_TYPE_INFO info ON info.tareget_type_code = detail.tareget_type_code where ti.user_id = #{userId} and ti.is_default = #{isDefault}
and info.tareget_type_code in ('01','02','03')
and info.tareget_type_code in ('04','05','06','07')

select t.tareget_code taregetCode , t.tareget_type_code tareget_type_code, t.tareget_name taregetName from TARGET_DETAIL t where t.is_default=#{isDefault}
and t.tareget_type_code in ('01','02','03')
and t.tareget_type_code in ('04','05','06','07')

		select cdate,'0.046' yield from PTL_PORTFOLIO_VALUATION


                AND CDATE >= #{startDate}


                AND #{endDate} >= CDATE


                AND PORTFOLIO_ID = #{portfolioId}

select #{startDate,jdbcType=DATE} cdate, yield from ( select EFF_DATE, t.INT_RATE yield from MST_INT_RATE_INFO t where t.INT_RATE != null
AND #{startDate,jdbcType=DATE} >= EFF_DATE
AND INT_RATE_ID = #{IntRateId}
AND INT_RATE_TYPE = #{IntRateType}
order by EFF_DATE desc ) where rownum = 1 union all select datas as cdate, T2.INT_RATE as yield from (SELECT #{startDate,jdbcType=DATE} + ROWNUM AS DATAS FROM DUAL CONNECT BY ROWNUM <= TRUNC(#{endDate,jdbcType=DATE} - #{startDate,jdbcType=DATE})) t1 left join (select t.INT_RATE, t.EFF_DATE from MST_INT_RATE_INFO t
AND EFF_DATE >= #{startDate,jdbcType=DATE}
AND #{endDate,jdbcType=DATE} >= EFF_DATE
AND INT_RATE_ID = #{IntRateId}
AND INT_RATE_TYPE = #{IntRateType}
) T2 on T2.EFF_DATE = t1.datas

select #{startDate,jdbcType=DATE} cdate, yield from ( select CURVE_DATE, t.YIELD yield from MST_YIELD_CURVE_INFO t where t.YIELD != null
AND #{startDate,jdbcType=DATE} >= CURVE_DATE
AND CURVE_CODE = #{curveCode}
order by CURVE_DATE desc ) where rownum = 1 union all select datas as cdate, T2.YIELD as yield from (SELECT #{startDate,jdbcType=DATE} + ROWNUM AS DATAS FROM DUAL CONNECT BY ROWNUM <= TRUNC(#{endDate,jdbcType=DATE} - #{startDate,jdbcType=DATE})) t1 left join (select t.YIELD, t.CURVE_DATE from MST_YIELD_CURVE_INFO t
AND CURVE_DATE >= #{startDate,jdbcType=DATE}
AND #{endDate,jdbcType=DATE} >= CURVE_DATE
AND CURVE_CODE = #{curveCode}
) T2 on T2.CURVE_DATE = t1.datas

select #{startDate,jdbcType=DATE} cdate, yield from ( select EFF_DATE, t.CLOSE_PRICE yield from MST_EXPONENT_QUOTATION t where t.INT_RATE != null
AND #{startDate,jdbcType=DATE} >= EFF_DATE
AND MARKET_ID = #{marketId}
order by EFF_DATE desc ) where rownum = 1 union all select datas as cdate, T2.CLOSE_PRICE as yield from (SELECT #{startDate,jdbcType=DATE} + ROWNUM AS DATAS FROM DUAL CONNECT BY ROWNUM <= TRUNC(#{endDate,jdbcType=DATE} - #{startDate,jdbcType=DATE})) t1 left join (select t.CLOSE_PRICE, t.EFF_DATE from MST_INT_RATE_INFO t
AND EFF_DATE >= #{startDate,jdbcType=DATE}
AND #{endDate,jdbcType=DATE} >= EFF_DATE
AND MARKET_ID = #{marketId}
) T2 on T2.EFF_DATE = t1.datas

  select datas as cdate, T2.int_rate as yield
  from (SELECT #{startDate,jdbcType=DATE} + ROWNUM - 1 AS DATAS
          FROM DUAL
        CONNECT BY ROWNUM <=
                   TRUNC(#{startDate,jdbcType=DATE} - #{endDate,jdbcType=DATE}) + 1) t1
  left join (select t.int_rate, t.eff_date
               from MST_INT_RATE_INFO t


		                AND EFF_DATE >= #{startDate,jdbcType=DATE}


		                AND #{endDate,jdbcType=DATE} >= EFF_DATE


		                AND INT_RATE_TYPE = #{intRateType}


		                AND INT_RATE_ID = #{intRateId}


		 ) T2
    on T2.eff_date = t1.datas
